    /// A test built on [`run_until`] must not leave its shell running once it
    /// ends: writing `release` only tells the shell to stop, it does not wait
    /// for it. What this checks is that [`FixtureRoot`] stops the run
    /// outright before its folder goes, rather than leaving the shell to
    /// notice `release` on its own — a notice it would never get, since
    /// `release` disappears along with the rest of the folder.
    #[test]
    fn a_command_step_test_leaves_no_shell_running_once_it_ends() {
        let release;
        let pids;
        {
            let (repo, _root_guard) = fixture("command-no-leak");
            add_task_with_worktree(&repo, "a-login", "implement");
            add_task_with_worktree(&repo, "b-export", "implement");
            release = repo.root.join("release");
            let pipelines = pipelines_running(&run_until(&release), false);
            let mux = FakeMux::new(vec![]);

            Dispatcher::new(&repo, &pipelines, &mux)
                .pass(&mut || {})
                .unwrap();

            let runs = crate::command_step::Runs::new(&repo.commands_dir());
            pids = ["a-login", "b-export"]
                .iter()
                .map(|task| {
                    runs.read_pid(&crate::command_step::Runs::key("implement", task))
                        .unwrap()
                })
                .collect::<Vec<_>>();

            std::fs::write(&release, "").unwrap();
        } // `_root_guard` drops here: it stops the runs, then deletes the scratch root.

        std::thread::sleep(Duration::from_millis(500));
        for pid in pids {
            assert!(
                !crate::headless::alive(pid),
                "a command shell under `{}` outlived its test",
                release.display()
            );
        }
    }

    /// The step that hands the change over, and what the pipeline says about it.
    ///
    /// `handover` is a command step — `run: spoolway stack`, no model and no
    /// rebase — and a failure now routes straight to `blocked` rather than
    /// to a second, LLM-run escalation step: `spoolway stack` calls `gh pr
    /// view` first, so re-running `handover` from `blocked` is safe. Three
    /// tests used to live here, one per value of `dispatch.merge`, each
    /// checking which capabilities the setting produced; then one, checking
    /// the `handover:` and `credentials:` flags that replaced them. Those
    /// went the same way — a pipeline says which prompt runs where, and
    /// every statement it made about reaching a forge belongs to the
    /// prompt's own prose instead.
    #[test]
    fn handover_runs_spoolway_stack_and_falls_back_to_blocked() {
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();

        let handover = pipeline.step("handover").expect("a hand-off step");
        assert!(
            handover.run.is_some(),
            "`handover` should run `spoolway stack`, not a prompt"
        );
        // No `on_fail:` of its own — that key would only repeat where a fail
        // already goes with none at all (see
        // `Pipeline::redundant_on_fail_warnings`) — so the routing this test
        // cares about is read from `destination`.
        assert_eq!(
            handover.destination(crate::pipeline::Outcome::Fail),
            Some(crate::pipeline::BLOCKED),
            "a failed `spoolway stack` should park the task for a person, not hand off \
             to a second agent step"
        );
    }

    /// A gated step and the plain step beside it are told the identical
    /// `situating` bullets and the identical `policy` — the gate fact is not
    /// advice about how to behave, it is a line the report contract states,
    /// and only the report contract differs between the two.
    #[test]
    fn a_gated_step_and_the_step_beside_it_differ_only_in_the_report_contract() {
        let (repo, _root_guard) = fixture("checkpoint-briefing");
        add_task(&repo, "t", "ask");
        let task = repo.task("t").unwrap();

        let pipeline = crate::pipeline::Pipeline::parse(
            "only",
            "steps:\n\
             \x20 - id: ask\n    agent: pi\n    gate: true\n    on_pass: deploy\n\
             \x20 - id: deploy\n    agent: pi\n    on_pass: done\n",
        )
        .expect("hand-built pipeline");

        let gated_step = pipeline.step("ask").unwrap();
        let plain_step = pipeline.step("deploy").unwrap();

        // `policy` carries no gate wording at all any more, for either step.
        let gated_policy = crate::compose::policy(&repo, &task, &pipeline, gated_step);
        let plain_policy = crate::compose::policy(&repo, &task, &pipeline, plain_step);
        assert_eq!(
            gated_policy, plain_policy,
            "policy no longer mentions a gate"
        );
        assert!(!gated_policy.to_lowercase().contains("gate"));

        // `situating` differs only by the step id — one wording, every lane.
        let gated_situating = crate::compose::situating(&pipeline, gated_step, &task, &repo)
            .unwrap()
            .replace("`ask`", "`X`");
        let plain_situating = crate::compose::situating(&pipeline, plain_step, &task, &repo)
            .unwrap()
            .replace("`deploy`", "`X`");
        assert_eq!(
            gated_situating, plain_situating,
            "situating no longer branches on whether the step is gated"
        );

        // The report contract is where the two finally differ: the gated
        // step's carries the fact, the plain one's does not.
        let gated_contract = crate::compose::report_contract(&task, &pipeline, gated_step);
        let plain_contract = crate::compose::report_contract(&task, &pipeline, plain_step);
        assert!(
            gated_contract.contains("A pass is held here for a person, who opens this pane."),
            "got: {gated_contract}"
        );
        assert!(
            !plain_contract.contains("held here for a person"),
            "got: {plain_contract}"
        );
    }

    /// A step with no `gate:` at all, and no `gate_at` naming it, gets no
    /// gate line at all — there is nothing to say, and saying it would
    /// invite a lane to stop where it never should.
    #[test]
    fn an_ungated_step_is_told_nothing_about_gates() {
        let (repo, _root_guard) = fixture("gate-silent");
        add_task(&repo, "t", "implement");
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();
        let step = pipeline.step("implement").unwrap();
        let task = repo.task("t").unwrap();

        assert!(!step.gate);
        let prompt = sent(&repo, &task, pipeline, step);
        assert!(!prompt.to_lowercase().contains("held here for a person"));
        assert!(!prompt.contains("dispatch.gates"));
    }

    /// `blocked`'s own bare `spoolway resume <task>` line is in its toolbox
    /// and nowhere else — no other step's system prompt should ever mention
    /// `READING THE RUN` or offer that line.
    #[test]
    fn only_blocked_names_the_bare_spoolway_resume_command() {
        let (repo, _root_guard) = fixture("only-blocked-names-resume");
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();
        let blocked_step = pipeline.step(crate::pipeline::BLOCKED).unwrap();
        let blocked_task = reload(&add_task(&repo, "t", crate::pipeline::BLOCKED));
        let blocked_prompt = sent(&repo, &blocked_task, pipeline, blocked_step);
        assert!(
            blocked_prompt.contains("READING THE RUN"),
            "{blocked_prompt}"
        );
        assert!(
            blocked_prompt.contains("`spoolway resume <task>`"),
            "{blocked_prompt}"
        );

        let implement_step = pipeline.step("implement").unwrap();
        let implement_task = reload(&add_task(&repo, "u", "implement"));
        let implement_prompt = sent(&repo, &implement_task, pipeline, implement_step);
        assert!(
            !implement_prompt.contains("READING THE RUN"),
            "{implement_prompt}"
        );
        // Only `blocked` names the bare command, in its toolbox.
        assert!(
            !implement_prompt.contains("`spoolway resume <task>`"),
            "{implement_prompt}"
        );
    }

    /// `YOUR LANE`'s route and person bullets, word for word: every lane is
    /// pointed at `queue route`, told to write a person's changes into the
    /// task file, and handed the one command that moves a resume. `blocked`
    /// keeps its own first bullet and gets no "another step's" sentence.
    #[test]
    fn your_lane_names_the_route_and_where_a_persons_changes_go() {
        let (repo, _root_guard) = fixture("lane-route-bullets");
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();
        let implement = pipeline.step("implement").unwrap();
        let task = reload(&add_task(&repo, "example", "implement"));

        let lane = crate::compose::situating(pipeline, implement, &task, &repo).unwrap();
        let bullets = "\
- One step's worth of the job, and nothing enforces it. Your role, below, is the whole of what is yours. Steps split the work for a reason; do not do another step's on your own.
- Your output is not read; only what you write to the task file reaches anyone. Ask nothing unless told to.
- Nothing will wake you. Poll anything you wait on.
- Reporting is the only exit. A turn ended any other way stalls the task.
- Commit as you go. Anything uncommitted is committed for you when you report.
- `spoolway queue route example` shows every step this task runs, what each does, and where resuming sends this task. Read it before you tell a person what happens next.
- If a person talks to you in this pane, do what they ask, whichever step's work it is. Write every change they ask for into the task file, so later steps see it: `spoolway task edit example --section <heading> --from -` while the task is held on `paused` or `blocked`, `--handoff` while it runs.
- Resuming a held task stays the person's: once their request is done, tell them where resuming sends it, and to resume it on the board.
- What a person has to do, name on the board, never as a `spoolway` command. To send the task to another step than resuming would, tell them to press `r` on its row and pick the step.";
        let flat = lane.split_whitespace().collect::<Vec<_>>().join(" ");
        let expected = bullets.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(flat.contains(&expected), "got: {lane}");
        assert!(!lane.contains("--stage"), "{lane}");

        let blocked = pipeline.step(crate::pipeline::BLOCKED).unwrap();
        let blocked_task = reload(&add_task(&repo, "stuck", crate::pipeline::BLOCKED));
        let lane = crate::compose::situating(pipeline, blocked, &blocked_task, &repo).unwrap();
        assert!(
            lane.contains("- Your remit is the run, not one task's step."),
            "{lane}"
        );
        assert!(!lane.contains("do not do another step's"), "{lane}");
        assert!(
            lane.contains("`spoolway queue route stuck` shows every step this task runs"),
            "{lane}"
        );
        assert!(lane.contains("`--handoff` while it runs."), "{lane}");
    }

    /// The Mockup this task is built from, word for word: a task blocked at
    /// `look` — a gated agent step — is told, in its own `THIS PASS`, which
    /// step its pass stands in for, that its craft is prompt `looker`, and
    /// where to read it; the toolbox gains the `spoolway prompt show <name>`
    /// line; and the report contract's `--stage` form names `look` as the
    /// furthest it may go, closing with the same "a pass is held here"
    /// sentence a gated step's own lane would get.
    #[test]
    fn the_unblockers_contract_names_the_gated_step_it_stands_in_for() {
        let (repo, _root_guard) = fixture("unblocker-gate-contract");
        let yaml = "steps:\n  \
                     - id: implement\n    agent: pi\n    on_pass: review\n  \
                     - id: review\n    agent: pi\n    on_pass: look\n  \
                     - id: look\n    \
                       description: Open the changed screen, drive it, and read back what it actually renders.\n    \
                       agent: pi\n    prompt: looker\n    gate: true\n    on_pass: e2e\n  \
                     - id: e2e\n    agent: pi\n    on_pass: done\n  \
                     - id: blocked\n    agent: pi\n    session: true\n";
        let pipeline = crate::pipeline::Pipeline::parse("impl_ui", yaml).unwrap();
        let blocked_step = pipeline.step(crate::pipeline::BLOCKED).unwrap();

        let task = reload(&add_task_with(
            &repo,
            "tab-shell",
            crate::pipeline::BLOCKED,
            |f| f.blocked_from = Some("look".into()),
        ));

        let prompt = sent(&repo, &task, &pipeline, blocked_step);
        assert!(
            prompt.contains(
                "`spoolway prompt show <name>` — the craft a step's lane is briefed with"
            ),
            "{prompt}"
        );
        assert!(
            prompt.contains(
                "`tab-shell` stopped at `look`: Open the changed screen, drive it, and read \
                 back what it actually renders. A plain pass stands in for that step's work. If \
                 you only cleared what stopped it, send it back to run again:\n\n    \
                 spoolway report --pass --stage look -m \"<one line on what happened>\"\n\n\
                 Its craft is prompt `looker`:\n`spoolway prompt show looker`."
            ),
            "{prompt}"
        );

        let contract = crate::compose::report_contract(&task, &pipeline, blocked_step);
        assert!(
            contract.contains("and never one past `look`."),
            "{contract}"
        );
        assert!(
            contract.contains("A pass is held here for a person, who opens this pane."),
            "{contract}"
        );
    }

    /// The command-step half of the same contract: `blocked_from` names a
    /// step whose craft is a shell command rather than a prompt, and this
    /// pass is told the command runs again once it carries the task past it
    /// — never a prompt to read that does not exist. Ungated, so the report
    /// contract's `--stage` form and trailing sentence both stay unchanged.
    #[test]
    fn the_unblockers_contract_names_a_command_steps_own_craft() {
        let (repo, _root_guard) = fixture("unblocker-command-contract");
        let yaml = "steps:\n  \
                     - id: build\n    run: cargo build --release\n    on_pass: done\n  \
                     - id: blocked\n    agent: pi\n    session: true\n";
        let pipeline = crate::pipeline::Pipeline::parse("solo", yaml).unwrap();
        let blocked_step = pipeline.step(crate::pipeline::BLOCKED).unwrap();

        let task = reload(&add_task_with(
            &repo,
            "release-cut",
            crate::pipeline::BLOCKED,
            |f| f.blocked_from = Some("build".into()),
        ));

        let prompt = sent(&repo, &task, &pipeline, blocked_step);
        assert!(
            prompt.contains(
                "`release-cut` stopped at `build`: A plain pass stands in for that step's work. \
                 Its craft is the command `cargo build --release`, which runs again once your \
                 pass carries this task past it."
            ),
            "{prompt}"
        );
        assert!(
            !prompt.contains("--pass --stage build"),
            "a command step is handed back to itself by a plain pass: {prompt}"
        );

        let contract = crate::compose::report_contract(&task, &pipeline, blocked_step);
        assert!(
            !contract.contains("A pass is held here for a person"),
            "{contract}"
        );
        assert!(
            contract.contains("again, or any step this task has already been through.\n\n"),
            "an ungated origin leaves the stage form's own explanation untouched: {contract}"
        );
    }

    /// The mechanics a prompt used to carry in a generated block are derived
    /// from the step instead, so they are sent exactly where they are true.
    ///
    /// The scratch space used to be a conditional paragraph naming
    /// `$SPOOLWAY_SCRATCH`, sent only to a step granted `rebase`. Every lane
    /// has one now — it is the lane's own directory, not a privilege — and it
    /// is a resolved path in `WHAT YOU HAVE` rather than a variable a prompt
    /// would have had to spell, so what a step is "told about it" means the
    /// path itself, not the name that resolves to it.
    #[test]
    fn the_opening_prompt_carries_only_the_mechanics_this_step_has() {
        let (repo, _root_guard) = fixture("prompt-mechanics");
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();
        let task = reload(&add_task(&repo, "demo", "review"));

        let sent_at = |step: &str| sent(&repo, &task, pipeline, pipeline.step(step).unwrap());

        for step in ["review", "handover", "implement"] {
            let prompt = sent_at(step);
            assert!(
                prompt.contains("scratch space"),
                "`{step}` has a scratch directory and is not told about it"
            );
            // And nothing spoolway sends still speaks the old vocabulary.
            for gone in ["SPOOLWAY_MERGE_INTO", "SPOOLWAY_ALLOW", "merge: git"] {
                assert!(
                    !prompt.contains(gone),
                    "`{gone}` reached `{step}`:\n{prompt}"
                );
            }
        }
    }

    /// The prompt contract's environment table is what somebody writing a
    /// prompt reads, and it is a separate list from the one a lane is
    /// actually started with. Nothing but this held them together, and they
    /// drifted: the contract went on offering `$SPOOLWAY_ALLOW` and
    /// `$SPOOLWAY_MERGE_INTO` for as long as it took somebody to notice, both
    /// of them gone with the capability system that set them.
    ///
    /// One direction only. A variable a lane sets and the contract does not
    /// mention is spoolway's own business — `$SPOOLWAY_HEAD`, which `report`
    /// reads to tell work from residue, is exactly that — but a variable the
    /// contract *promises* and no lane sets is a prompt written against
    /// something that will not be there.
    #[test]
    fn the_prompt_contract_promises_no_variable_a_lane_lacks() {
        let (repo, _root_guard) = fixture("contract-environment");
        add_task(&repo, "demo", "queued");
        let mux = FakeMux::new(vec![]);

        run_pass(&repo, &mux);

        let started = mux.did("env");
        let line = started.first().expect("no lane was started");
        for (name, _) in crate::prompt::ENVIRONMENT {
            assert!(
                line.split(' ').any(|set| set == *name),
                "the contract promises `{name}`, which no lane sets: {line}"
            );
        }
    }

    /// Every lane opens by being told what it is inside of. Without it a model
    /// reads a task file and a role and infers a solo assignment — so it widens
    /// its scope past the step it was given, asks a question into a pane nobody
    /// reads, or treats a boundary it was told about as an obstacle to work
    /// around rather than the edge of the step. Each
    /// of those is a lane that has to be fetched a person, and each is answered
    /// by one paragraph naming the step and the task it actually has.
    #[test]
    fn every_lane_is_told_it_is_one_step_of_one_task_in_spoolway() {
        let (repo, _root_guard) = fixture("prompt-situation");
        let pipelines = Pipelines::builtin();

        for (pipeline, step) in [
            ("default", "implement"),
            ("default", "handover"),
            ("default", "document"),
            ("bugfix", "reproduce"),
        ] {
            let pipeline = pipelines.get(pipeline).unwrap();
            let task = reload(&add_task(&repo, "demo", step));
            let prompt = sent(&repo, &task, pipeline, pipeline.step(step).unwrap());

            assert!(
                prompt.contains("spoolway runs one task at a time"),
                "{prompt}"
            );
            assert!(prompt.contains("You are a lane"), "{prompt}");
            // Named, not gestured at: "your step" is a phrase, `merge` is a
            // fact the lane can check itself against.
            assert!(prompt.contains(&format!("step `{step}`")), "{prompt}");
            assert!(prompt.contains("task `demo`"), "{prompt}");
            assert!(
                prompt.contains(
                    "Your output is not read; only what you write to the task \
                                  file reaches anyone"
                ),
                "{prompt}"
            );
            // And it is in the *system* prompt, not the typed message: the
            // whole point of composing is that a project cannot drop it by
            // writing its own prompt.
            assert!(
                crate::compose::system_prompt(
                    &repo,
                    &task,
                    pipeline,
                    pipeline.step(step).unwrap(),
                    "[prompt]"
                )
                .unwrap()
                .contains("spoolway runs one task at a time"),
                "the framing must survive in the system prompt alone"
            );
        }
    }

    /// A lane is told that nothing resumes a settled session — a lane that
    /// backgrounds a wait and ends its turn instead leaves a pane the board
    /// reports as a question.
    #[test]
    fn every_lane_is_told_that_nothing_will_wake_it() {
        let (repo, _root_guard) = fixture("prompt-no-wakeup");
        let pipelines = Pipelines::builtin();
        let pipeline = pipelines.get("default").unwrap();
        let step = pipeline.step("handover").unwrap();
        let task = reload(&add_task(&repo, "demo", "handover"));

        let prompt = sent(&repo, &task, pipeline, step);
        assert!(prompt.contains("Nothing will wake you"), "{prompt}");
        for gone in ["background job", "timer"] {
            assert!(!prompt.contains(gone), "`{gone}` still named:\n{prompt}");
        }
        assert!(prompt.contains("Poll anything you wait on"), "{prompt}");
    }

    /// `opening_prompt` used to carry the whole report contract, then just a
    /// pointer to it; now it carries neither. One sentence naming the task
