            add_task_with(&repo, "demo", "review", |f| {
                f.workspace_id = Some("w1".into());
                f.tab_id = Some("w1:t1".into());
                f.pane_id = Some("w1:p1".into());
                f.worktree_path = Some(worktree.to_path_buf());
            });
